#include <stdio.h>
#include <stdlib.h>

void* rc_new(int size) {
    int *mem = malloc(sizeof(int) + size);
    *mem = 1;
    return mem + 1;
}

void* rc_ref(void *ptr) {
    int *rc = (int*)ptr - 1;
    (*rc)++;
    return ptr;
}

void rc_unref(void *ptr) {
    int *rc = (int*)ptr - 1;
    (*rc)--;
    printf("Refcount: %d\n", *rc);
    if (*rc == 0) {
        free(rc);
        printf("Memory freed\n");
    }
}

int main() {
    int *data = (int*)rc_new(10 * sizeof(int));
    data[0] = 42;
    int *data2 = (int*)rc_ref(data);
    rc_unref(data);
    rc_unref(data2);
    return 0;
}
